{
  const scroll = $('#agd-scroll');
  const days = [
    { o:0, ev:[
      { k:'m', who:'Maya Chen', t:'Kickoff with Northwind', s:'9:00 to 9:45 AM', d:'Agree scope, owners and the launch date with the Northwind team.', past:true },
      { now:true },
      { k:'b', who:'Oscar Lind', t:'Pricing page review', s:'1:30 to 2:30 PM', d:'Walk through the comparison table and settle the plan names before handoff.' },
      { k:'l', who:'Priya Nair', t:'Design system workshop', s:'4:00 to 5:30 PM', d:'Merge the button and input variants into one token set, laptops needed.' }
    ]},
    { o:1, ev:[
      { k:'m', who:'Tom Becker', t:'Weekly client sync', s:'10:00 to 10:30 AM', d:'Status update on the brand refresh and the open questions on logo usage.' },
      { k:'r', icon:'schedule', t:'Copy freeze', s:'End of day', d:'All website copy locked so the team can finish translations.' }
    ]},
    { o:3, ev:[
      { k:'r', icon:'bolt', t:'Design sign-off', s:'All day', d:'Final approval on every page before development starts on Monday.' },
      { k:'b', who:'Ines Duarte', t:'Onboarding flow review', s:'2:00 to 3:00 PM', d:'Review the shorter onboarding and the new workspace step with research notes.' }
    ]},
    { o:4, ev:[
      { k:'l', who:'Joanna Kim', t:'Motion jam', s:'11:00 to 12:00 PM', d:'Prototype the new page transitions together and record the best take.' },
      { k:'m', who:'Jonas Weber', t:'Quarterly planning call', s:'3:00 to 4:00 PM', d:'Plan next quarter and agree where the retainer hours go first.' }
    ]}
  ];
  const type = e => e.k === 'r' ? 'due' : 'meet';
  scroll.innerHTML = days.map(g => {
    const d = addDays(TODAY, g.o);
    return `<div class="agd-g ${g.o === 0 ? 'today' : ''}"><div class="agd-day"><span class="wd">${d.toLocaleDateString('en-GB', { weekday:'short' })}</span><span class="n">${d.getDate()}</span></div><div class="agd-list">${g.ev.map(e => e.now ? '<div class="agd-now"><span>Now</span></div>' :
      `<button class="agd-c ev-${e.k} ${e.past ? 'past' : ''}" data-t="${type(e)}">${e.who ? avatar(e.who) : `<span class="agd-ic">${ic(e.icon,'sm')}</span>`}<span class="agd-tx"><span class="agd-tt">${e.t}</span><span class="agd-tm" style="display:block">${e.s}</span><span class="agd-ds">${e.d}</span></span></button>`).join('')}</div></div>`;
  }).join('');
  scroll.addEventListener('click', e => { const c = e.target.closest('.agd-c'); if (!c) return; c.classList.toggle('open'); Sound.play(c.classList.contains('open') ? 'open' : 'close'); });
  tabHandlers.agd = v => {
    morph($('#agd'), () => {
      $$('.agd-c', scroll).forEach(c => c.classList.toggle('hide', v !== 'all' && c.dataset.t !== v));
      $$('.agd-now', scroll).forEach(n => n.classList.toggle('hide', v !== 'all'));
      $$('.agd-g', scroll).forEach(g => { g.classList.toggle('hide', !$$('.agd-c:not(.hide)', g).length); $$('.agd-c:not(.hide)', g).forEach((c, i) => { c.classList.remove('enter'); void c.offsetWidth; c.classList.add('enter'); c.style.animationDelay = i * 50 + 'ms'; }); });
    });
  };
}
